  def testCssOneSelectorPerLine(self):
    self.VerifyContentsProducesOutput(
        """
a,
div,a,
div,/* Hello! */ span,
#id.class([dir=rtl]):not(.class):any(a, b, d),
div :is(:not(a), #b, .c) {
